}

await browser.close();
console.log(failures ? `\n${failures} FAILED` : '\nall browser checks passed');
process.exit(failures ? 1 : 0);

// Deterministic generator for the spike-only multi-system fixture.
// Emits fixtures/multisystem_concert.musicxml following the ENG-001 ID rules:
//   canonical note -> hs-sn-<6 digits>         (fragment k>1 -> hs-sn-<6 digits>-k)
//   rest           -> hs-rest-<6 digits>        (presentation-only)
// Run: npm run gen:multisystem   (output is committed; regenerate only to change content)

import { writeFileSync } from 'node:fs';
import { fileURLToPath } from 'node:url';
import { dirname, join } from 'node:path';

const here = dirname(fileURLToPath(import.meta.url));
const outPath = join(here, '..', 'fixtures', 'multisystem_concert.musicxml');

const DIVISIONS = 480; // ticks per quarter note
const MEASURES = 24;
const QUARTER = DIVISIONS;
const EIGHTH = DIVISIONS / 2;
const HALF = DIVISIONS * 2;
const WHOLE = DIVISIONS * 4;

let noteSeq = 0;
let restSeq = 0;
const snId = () => `hs-sn-${String(++noteSeq).padStart(6, '0')}`;
const restId = () => `hs-rest-${String(++restSeq).padStart(6, '0')}`;

function pitchNote({ id, step, alter = 0, octave, duration, type, dots = 0, tie = null, accidental = null }) {
  const lines = [];
  lines.push(`      <note id="${id}">`);
  lines.push('        <pitch>');
  lines.push(`          <step>${step}</step>`);
  if (alter !== 0) lines.push(`          <alter>${alter}</alter>`);
  lines.push(`          <octave>${octave}</octave>`);
  lines.push('        </pitch>');
  lines.push(`        <duration>${duration}</duration>`);
  if (tie === 'stop' || tie === 'stopstart') lines.push('        <tie type="stop" />');
  if (tie === 'start' || tie === 'stopstart') lines.push('        <tie type="start" />');
  lines.push(`        <type>${type}</type>`);
  for (let i = 0; i < dots; i++) lines.push('        <dot />');
  if (accidental) lines.push(`        <accidental>${accidental}</accidental>`);
  if (tie) {
    lines.push('        <notations>');
    if (tie === 'stop' || tie === 'stopstart') lines.push('          <tied type="stop" />');
    if (tie === 'start' || tie === 'stopstart') lines.push('          <tied type="start" />');
    lines.push('        </notations>');
  }
  lines.push('      </note>');
  return lines.join('\n');
}

function restNote({ duration, type, dots = 0 }) {
  return [
    `      <note id="${restId()}">`,
    '        <rest />',
    `        <duration>${duration}</duration>`,
    `        <type>${type}</type>`,
    ...(dots ? Array.from({ length: dots }, () => '        <dot />') : []),
    '      </note>',
  ].join('\n');
}

// Scale degree pattern in D major written pitch space (fixture is "concert" labelled,
// content only needs to be valid + deterministic for the rendering spike).
const STEPS = [
  { step: 'D', octave: 5 }, { step: 'E', octave: 5 }, { step: 'F', alter: 1, octave: 5 },
  { step: 'G', octave: 5 }, { step: 'A', octave: 5 }, { step: 'B', octave: 4 },
  { step: 'C', alter: 1, octave: 5 }, { step: 'D', octave: 5 },
];

const measures = [];
for (let m = 1; m <= MEASURES; m++) {
  const body = [];
  if (m === 1) {
    body.push(`      <attributes>
        <divisions>${DIVISIONS}</divisions>
        <key>
          <fifths>2</fifths>
        </key>
        <time>
          <beats>4</beats>
          <beat-type>4</beat-type>
        </time>
        <clef>
          <sign>G</sign>
          <line>2</line>
        </clef>
      </attributes>`);
    body.push(`      <direction>
        <direction-type>
          <metronome parentheses="no">
            <beat-unit>quarter</beat-unit>
            <per-minute>120</per-minute>
          </metronome>
        </direction-type>
        <sound tempo="120" />
      </direction>`);
  }
  if (m === 9) {
    // chromatic color: explicit G# and Bb accidentals in a G-major-ish bar
    body.push(pitchNote({ id: snId(), step: 'G', alter: 1, octave: 4, duration: QUARTER, type: 'quarter', accidental: 'sharp' }));
    body.push(pitchNote({ id: snId(), step: 'B', alter: -1, octave: 4, duration: QUARTER, type: 'quarter', accidental: 'flat' }));
    body.push(pitchNote({ id: snId(), step: 'A', octave: 4, duration: EIGHTH, type: 'eighth' }));
    body.push(pitchNote({ id: snId(), step: 'B', octave: 4, duration: EIGHTH, type: 'eighth' }));
    body.push(restNote({ duration: QUARTER, type: 'quarter' }));
  } else if (m === 11) {
    // canonical note tied across the barline: dotted quarter -> half + eighth (3 fragments)
    body.push(pitchNote({ id: snId(), step: 'A', octave: 4, duration: QUARTER, type: 'quarter' }));
    body.push(pitchNote({ id: snId(), step: 'B', octave: 4, duration: QUARTER, type: 'quarter' }));
    const tiedId = snId(); // fragment 1 carries the canonical export id
    body.push(pitchNote({ id: tiedId, step: 'D', octave: 5, duration: QUARTER + EIGHTH, type: 'quarter', dots: 1, tie: 'start' }));
    body.push(restNote({ duration: EIGHTH, type: 'eighth' }));
  } else if (m === 12) {
    const canonical = noteSeq; // continue the tie from m.11
    body.push(pitchNote({ id: `hs-sn-${String(canonical).padStart(6, '0')}-2`, step: 'D', octave: 5, duration: HALF, type: 'half', tie: 'stopstart' }));
    body.push(pitchNote({ id: `hs-sn-${String(canonical).padStart(6, '0')}-3`, step: 'D', octave: 5, duration: EIGHTH, type: 'eighth', tie: 'stop' }));
    body.push(pitchNote({ id: snId(), step: 'E', octave: 5, duration: EIGHTH, type: 'eighth' }));
    body.push(pitchNote({ id: snId(), step: 'D', octave: 5, duration: QUARTER, type: 'quarter' }));
    body.push(restNote({ duration: QUARTER, type: 'quarter' }));
  } else if (m === 16) {
    // full-measure rest
    body.push(restNote({ duration: WHOLE, type: 'whole' }));
  } else if (m === 20) {
    // half note tied across the barline into m.21 (2 fragments)
    body.push(pitchNote({ id: snId(), step: 'F', alter: 1, octave: 5, duration: QUARTER, type: 'quarter' }));
    body.push(pitchNote({ id: snId(), step: 'E', octave: 5, duration: QUARTER, type: 'quarter' }));
    const tiedId = snId(); // fragment 1 carries the canonical export id
    body.push(pitchNote({ id: tiedId, step: 'D', octave: 5, duration: HALF, type: 'half', tie: 'start' }));
  } else if (m === 21) {
    const canonical = noteSeq; // continue tie from m.20
    body.push(pitchNote({ id: `hs-sn-${String(canonical).padStart(6, '0')}-2`, step: 'D', octave: 5, duration: HALF, type: 'half', tie: 'stop' }));
    body.push(pitchNote({ id: snId(), step: 'C', alter: 1, octave: 5, duration: QUARTER, type: 'quarter' }));
    body.push(pitchNote({ id: snId(), step: 'D', octave: 5, duration: QUARTER, type: 'quarter' }));
  } else {
    // default: four eighth-pair + quarter pattern cycling STEPS
    const base = (m * 3) % STEPS.length;
    body.push(pitchNote({ id: snId(), ...STEPS[base % STEPS.length], duration: QUARTER, type: 'quarter' }));
    body.push(pitchNote({ id: snId(), ...STEPS[(base + 2) % STEPS.length], duration: EIGHTH, type: 'eighth' }));
    body.push(pitchNote({ id: snId(), ...STEPS[(base + 4) % STEPS.length], duration: EIGHTH, type: 'eighth' }));
    body.push(pitchNote({ id: snId(), ...STEPS[(base + 5) % STEPS.length], duration: QUARTER, type: 'quarter' }));
    body.push(pitchNote({ id: snId(), ...STEPS[(base + 6) % STEPS.length], duration: QUARTER, type: 'quarter' }));
  }
  measures.push(`    <measure implicit="no" number="${m}">\n${body.join('\n')}\n    </measure>`);
}

const xml = `<?xml version="1.0" encoding="utf-8"?>
<!DOCTYPE score-partwise PUBLIC "-//Recordare//DTD MusicXML 4.0 Partwise//EN" "http://www.musicxml.org/dtds/partwise.dtd">
<score-partwise version="4.0">
  <work>
    <work-title>Multisystem Fixture (spike)</work-title>
  </work>
  <movement-title>Multisystem Fixture</movement-title>
  <identification>
    <creator type="composer">HornScribe spike generator</creator>
    <encoding>
      <software>apps/spikes/score-render/scripts/gen-multisystem.mjs</software>
      <supports element="beam" type="yes" />
      <supports element="stem" type="yes" />
      <supports element="accidental" type="yes" />
    </encoding>
  </identification>
  <defaults>
    <scaling>
      <millimeters>7</millimeters>
      <tenths>40</tenths>
    </scaling>
  </defaults>
  <part-list>
    <score-part id="P1">
      <part-name>Horn in F</part-name>
    </score-part>
  </part-list>
  <part id="P1">
${measures.join('\n')}
  </part>
</score-partwise>
`;

writeFileSync(outPath, xml, 'utf8');
console.log(`wrote ${outPath} (${noteSeq} canonical notes, ${restSeq} rests, ${MEASURES} measures)`);

/**
 * UI-003 node smoke test — runs the real Verovio WASM toolkit in Node against
 * the committed ENG-001 fixtures and asserts the mappings the issue requires:
 *
 *   MusicXML note/@id  ->  rendered SVG element id        (verovio pass-through)
 *   rendered element   ->  canonical sn-* id              (ids.ts, same file the app uses)
 *   canonical id       ->  all rendered fragments          (hs-sn-*-k tie splits)
 *   element            ->  onset time                      (getTimeForElement)
 *   time               ->  elements                        (getElementsAtTime)
 *   element            ->  page                            (getPageWithElement)
 *   reload / Concert↔Horn -> identical canonical mapping   (stability)
 *   corrupt input      ->  recoverable on same toolkit     (failure recovery)
 *
 * DOM assertions use jsdom against the actual SVG string. Run: `npm run smoke`.
 */
import { readFileSync } from 'node:fs';
import { fileURLToPath } from 'node:url';
import { dirname, join } from 'node:path';
import { JSDOM } from 'jsdom';
import createVerovioModule from 'verovio/wasm';
import { VerovioToolkit } from 'verovio/esm';
// Node 24 strips types for .ts imports — this is the *same* module the app uses.
import {
  canonicalNoteIdFromMusicxml,
  isMusicxmlNoteId,
  isMusicxmlRestId,
} from '../src/lib/ids.ts';

const here = dirname(fileURLToPath(import.meta.url));
const repoRoot = join(here, '..', '..', '..', '..');
const spikeRoot = join(here, '..');

const FIXTURES = {
  golden_concert: join(repoRoot, 'fixtures/musicxml/golden_v1_concert.musicxml'),
  golden_horn: join(repoRoot, 'fixtures/musicxml/golden_v1_horn_in_f.musicxml'),
  minimal_concert: join(repoRoot, 'fixtures/musicxml/minimal_v1_concert.musicxml'),
  minimal_horn: join(repoRoot, 'fixtures/musicxml/minimal_v1_horn_in_f.musicxml'),
  multisystem: join(spikeRoot, 'fixtures/multisystem_concert.musicxml'),
};

const OPTS = { pageWidth: 2100, pageHeight: 1100, scale: 40, adjustPageHeight: false, footer: 'none' };

let failures = 0;
const results = { measurements: {}, checks: [] };

function check(name, cond, detail = '') {
  results.checks.push({ name, pass: !!cond, detail });
  if (cond) console.log(`  ok   ${name}${detail ? ` — ${detail}` : ''}`);
  else {
    failures++;
    console.log(`  FAIL ${name}${detail ? ` — ${detail}` : ''}`);
  }
}

function timed(label, fn) {
  const t0 = performance.now();
  const out = fn();
  const ms = performance.now() - t0;
  (results.measurements[label] ??= []).push(ms);
  return out;
}

const noteIds = (xml) => [...xml.matchAll(/<note id="([^"]+)"/g)].map((m) => m[1]);
const svgIds = (svg) => new Set([...svg.matchAll(/id="([^"]+)"/g)].map((m) => m[1]));

console.log('== UI-003 smoke: Verovio WASM x ENG-001 fixtures ==\n');

// --- 1. toolkit init ---------------------------------------------------------
const tInit = performance.now();
const module_ = await createVerovioModule();
const tk = new VerovioToolkit(module_);
results.measurements.wasmInit = [performance.now() - tInit];
tk.setOptions(OPTS);
console.log(`toolkit ready (verovio ${tk.getVersion()})`);

// --- 2. per-fixture render + id pass-through ---------------------------------
const rendered = {};
for (const [name, path] of Object.entries(FIXTURES)) {
  const xml = readFileSync(path, 'utf8');
  const ok = timed(`loadData:${name}`, () => tk.loadData(xml));
  // loadData returns 1/0, not a boolean — and (see below) may return 1 for
  // truncated-but-parseable XML, so content checks must complement it.
  check(`${name}: loadData accepted`, !!ok);
  const firstSvg = timed(`renderToSVG(p1):${name}`, () => tk.renderToSVG(1));
  const pages = tk.getPageCount();
  const pagesSvg = [firstSvg];
  for (let p = 2; p <= pages; p++) pagesSvg.push(timed(`renderToSVG(p${p}):${name}`, () => tk.renderToSVG(p)));
  const allSvg = pagesSvg.join('\n');
  const ids = svgIds(allSvg);
  const expected = noteIds(xml);
  const missing = expected.filter((id) => !ids.has(id));
  check(`${name}: every MusicXML note/@id rendered into SVG`, missing.length === 0,
    `${expected.length} ids, missing=${missing.length}${missing.length ? ' ' + missing.join(',') : ''}`);
  rendered[name] = { xml, svg: allSvg, pages };
  console.log(`       ${name}: ${pages} page(s), ${expected.length} note elements`);
}

// --- 3. canonical id resolution (same code path as the app) ------------------
check('hs-sn-000003-2 -> sn-000003', canonicalNoteIdFromMusicxml('hs-sn-000003-2') === 'sn-000003');
check('hs-sn-000003   -> sn-000003', canonicalNoteIdFromMusicxml('hs-sn-000003') === 'sn-000003');
check('hs-rest-000001 -> null (no canonical)', canonicalNoteIdFromMusicxml('hs-rest-000001') === null);
check('isMusicxmlNoteId accepts fragments', isMusicxmlNoteId('hs-sn-000003-12') === true);
check('isMusicxmlRestId detects rests', isMusicxmlRestId('hs-rest-000002') === true);

// --- 4. DOM hit-test on real SVG (jsdom) -------------------------------------
{
  const dom = new JSDOM(rendered.golden_concert.svg, { contentType: 'image/svg+xml' });
  const doc = dom.window.document;
  const frag = doc.getElementById('hs-sn-000003-2');
  check('jsdom: getElementById finds tied fragment', frag !== null);
  check('fragment is a <g class="note">', frag?.getAttribute('class') === 'note');
  const noteEl = frag?.closest('g.note') ?? null;
  check('closest(g.note) hit-test resolves group', noteEl?.id === 'hs-sn-000003-2');
  check('DOM element -> canonical sn-000003', canonicalNoteIdFromMusicxml(noteEl?.id ?? '') === 'sn-000003');
  // all 3 fragments of sn-000003 render as separate elements sharing canonical id
  const frags = ['hs-sn-000003', 'hs-sn-000003-2', 'hs-sn-000003-3'].map((id) => doc.getElementById(id));
  check('all 3 tie fragments present as distinct elements', frags.every(Boolean));
  check('fragments share canonical id', new Set(frags.map((f) => canonicalNoteIdFromMusicxml(f.id))).size === 1);
  // highlight class toggle on the real elements — the no-re-render update path
  const t = performance.now();
  for (let i = 0; i < 1000; i++) for (const f of frags) f.classList.toggle('hs-selected', i % 2 === 0);
  results.measurements.highlightToggle1000 = [performance.now() - t];
  frags.forEach((f) => f.classList.add('hs-selected'));
  check('classList highlight applies to SVG elements', frags.every((f) => f.classList.contains('hs-selected')));
}

// --- 5. time <-> element mapping ----------------------------------------------
{
  tk.loadData(rendered.golden_concert.xml);
  timed('renderToTimemap:golden', () => tk.renderToTimemap());
  const t1 = timed('getTimeForElement:hs-sn-000001', () => tk.getTimeForElement('hs-sn-000001'));
  const t3 = tk.getTimeForElement('hs-sn-000003');
  const t3f2 = tk.getTimeForElement('hs-sn-000003-2');
  const t3f3 = tk.getTimeForElement('hs-sn-000003-3');
  check('element -> time: onsets are ordered', t1 === 0 && t3 === 1500 && t3f2 === 2400 && t3f3 === 3600,
    `0/1500/2400/3600 ms @100bpm got ${[t1, t3, t3f2, t3f3].join('/')}`);
  const at = timed('getElementsAtTime:2500', () => tk.getElementsAtTime(2500));
  check('time -> elements: 2.5s hits tied fragment hs-sn-000003-2',
    Array.isArray(at?.notes) && at.notes.includes('hs-sn-000003-2'), JSON.stringify(at?.notes));
  check('time -> elements resolves canonical', canonicalNoteIdFromMusicxml(at?.notes?.[0] ?? '') === 'sn-000003');
  // Finding: getElementsAtTime never reports MusicXML rests in `rests[]` —
  // rests carry no canonical identity in HornScribe anyway, so only the field's
  // presence and the absence of hs-rest-* from `notes` are asserted.
  const atRest = tk.getElementsAtTime(5000); // m.3: hs-rest-000002 spans this time
  check('rests field exists; no hs-rest-* surfaces in notes[]',
    Array.isArray(atRest?.rests) && !(atRest?.notes ?? []).some((n) => isMusicxmlRestId(n)),
    JSON.stringify(atRest));
  check('element -> page', tk.getPageWithElement('hs-sn-000004') === 1);
  const multi = rendered.multisystem;
  tk.loadData(multi.xml);
  check('multisystem fixture paginates (>1 page)', tk.getPageCount() > 1, `pages=${tk.getPageCount()}`);
  check('element -> page across pages', tk.getPageWithElement('hs-sn-000104') === tk.getPageCount());
}

// --- 6. stability across reload + Concert<->Horn ------------------------------
{
  const tk2 = new VerovioToolkit(module_);
  tk2.setOptions(OPTS);
  tk2.loadData(rendered.golden_concert.xml);
  const ids2 = svgIds(tk2.renderToSVG(1));
  check('fresh toolkit instance reproduces identical element ids',
    ['hs-sn-000001', 'hs-sn-000003', 'hs-sn-000003-2', 'hs-sn-000003-3', 'hs-rest-000001']
      .every((id) => ids2.has(id)));

  tk.loadData(rendered.golden_horn.xml);
  const hornIds = svgIds(tk.renderToSVG(1));
  const canonicalInHorn = [...hornIds].filter((i) => i.startsWith('hs-sn-')).map(canonicalNoteIdFromMusicxml);
  check('Horn presentation keeps identical export ids',
    ['hs-sn-000001', 'hs-sn-000002', 'hs-sn-000003', 'hs-sn-000003-2', 'hs-sn-000003-3', 'hs-sn-000004']
      .every((id) => hornIds.has(id)));
  check('Horn presentation resolves identical canonical ids',
    JSON.stringify(canonicalInHorn) === JSON.stringify(['sn-000001', 'sn-000002', 'sn-000003', 'sn-000003', 'sn-000003', 'sn-000004']),
    canonicalInHorn.join(','));
}

// --- 6b. ScoreRenderer wrapper (the same module the app uses) ------------------
{
  const { ScoreRenderer } = await import('../src/lib/verovio.ts');
  const r = new ScoreRenderer();
  await r.init();
  r.setZoom(100);
  check('wrapper: load golden', !!r.load(readFileSync(FIXTURES.golden_concert, 'utf8')));
  check('wrapper: renderAllPages returns pages', r.renderAllPages().length >= 1);
  const tm = r.timemap();
  check('wrapper: timemap parses (array)', Array.isArray(tm) && tm.length > 0, `${tm.length} entries`);
  check('wrapper: durationMs = 7200 (golden @100bpm, 12 quarters)', r.durationMs() === 7200, `${r.durationMs()}`);
  check('wrapper: timeForElement fragment', r.timeForElement('hs-sn-000003-2') === 2400);
  check('wrapper: elementsAtTime', r.elementsAtTime(2500)?.notes?.includes('hs-sn-000003-2'));
  check('wrapper: pageWithElement', r.pageWithElement('hs-sn-000004') === 1);
}

// --- 7. failure recovery -------------------------------------------------------
{
  const okBad = tk.loadData('not xml at all');
  check('non-XML input rejected (loadData falsy, no throw)', !okBad);
  // Caveat for the real app: truncated-but-well-formed XML returns 1 yet
  // renders an empty score — the UI must also verify content, not just `ok`.
  const okTrunc = tk.loadData('<score-partwise version="4.0"><part><measure>');
  const truncHasNotes = okTrunc ? /class="note"/.test(tk.renderToSVG(1)) : false;
  check('truncated XML: loadData=1 but zero notes (needs content check)',
    okTrunc === 1 && !truncHasNotes);
  const okGood = tk.loadData(rendered.golden_concert.xml);
  check('same toolkit instance recovers and renders again',
    !!okGood && tk.renderToSVG(1).includes('hs-sn-000001'));
}

// --- 8. zoom-level render timing (50/100/150/200% -> scale 20/40/60/80) --------
{
  const xml = readFileSync(FIXTURES.multisystem, 'utf8');
  for (const scale of [20, 40, 60, 80]) {
    tk.setOptions({ ...OPTS, scale });
    tk.loadData(xml);
    timed(`renderAllPages:multisystem:scale${scale}`, () => {
      const p1 = tk.renderToSVG(1);
      for (let p = 2; p <= tk.getPageCount(); p++) tk.renderToSVG(p);
      return p1;
    });
  }
  // repeated load+render of the golden pair (switch cost)
  for (let i = 0; i < 5; i++) {
    timed('loadData:golden_concert:warm', () => tk.loadData(readFileSync(FIXTURES.golden_concert, 'utf8')));
    timed('renderToSVG(p1):golden:warm', () => tk.renderToSVG(1));
    timed('loadData:golden_horn:warm', () => tk.loadData(readFileSync(FIXTURES.golden_horn, 'utf8')));
    timed('renderToSVG(p1):horn:warm', () => tk.renderToSVG(1));
  }
}

// --- summary -------------------------------------------------------------------
console.log('\n== measurements (ms) ==');
for (const [k, v] of Object.entries(results.measurements)) {
  const avg = v.reduce((a, b) => a + b, 0) / v.length;
  console.log(`  ${k.padEnd(38)} n=${v.length} last=${v[v.length - 1].toFixed(2)} avg=${avg.toFixed(2)}`);
}
const passed = results.checks.filter((c) => c.pass).length;
console.log(`\n== ${passed}/${results.checks.length} checks passed${failures ? `, ${failures} FAILED` : ''} ==`);
process.exit(failures ? 1 : 0);

import { useCallback, useEffect, useLayoutEffect, useReducer, useRef, useState } from 'react';
import { getScoreRenderer, type RenderedPage, type ScoreRenderer } from './lib/verovio';
import {
  buildElementIndex,
  markCanonical,
  markCanonicalSet,
  ACTIVE_CLASS,
  SELECTED_CLASS,
  type ElementIndex,
} from './lib/domScore';
import { canonicalNoteIdFromMusicxml } from './lib/ids';
import { parseScoreDoc, describeNote, pitchLabel, type ScoreDoc } from './lib/scoreDoc';
import { metrics, formatMs } from './lib/perf';
import { copy, spikeCopy } from './copy';
import { fixtureXml, supportsHorn, type FixtureSetId, type PitchView } from './fixtures';
import { ScoreView } from './components/ScoreView';
import { NoteList } from './components/NoteList';

type RenderReason = 'initial' | 'fixture' | 'switch' | 'zoom' | 'retry' | 'inject';

interface Selection {
  exportId: string;
  canonicalId: string | null;
  onsetMs: number | null;
  page: number;
}

export default function App() {
  const rendererRef = useRef<ScoreRenderer | null>(null);
  const scoreRef = useRef<HTMLDivElement>(null);
  const indexRef = useRef<ElementIndex | null>(null);
  const didInit = useRef(false);

  const [fixtureSet, setFixtureSet] = useState<FixtureSetId>('golden');
  const [view, setView] = useState<PitchView>('concert');
  const [zoom, setZoom] = useState(100);
  const [pages, setPages] = useState<RenderedPage[]>([]);
  const [scoreDoc, setScoreDoc] = useState<ScoreDoc | null>(null);
  const [durationMs, setDurationMs] = useState(0);
  const [timeMs, setTimeMs] = useState(0);
  const [activeExportIds, setActiveExportIds] = useState<string[]>([]);
  const [selection, setSelection] = useState<Selection | null>(null);
  const [renderError, setRenderError] = useState(false);
  const [initError, setInitError] = useState<string | null>(null);
  const [version, setVersion] = useState('');
  const [, bump] = useReducer((x: number) => x + 1, 0);

  // Refs mirrored so the post-render layout effect always sees fresh values.
  const selectionRef = useRef<Selection | null>(null);
  const activeCanonicalsRef = useRef<Set<string>>(new Set());

  const renderScore = useCallback(
    (reason: RenderReason, opts: { set?: FixtureSetId; v?: PitchView; z?: number; broken?: boolean } = {}) => {
      const r = rendererRef.current;
      if (!r) return;
      const setId = opts.set ?? fixtureSet;
      const v = opts.v ?? view;
      const z = opts.z ?? zoom;
      const tAll = performance.now();
      try {
        r.setZoom(z);
        const xml = opts.broken ? 'corrupt payload: this is not MusicXML' : fixtureXml(setId, v);
        const ok = metrics.measure('loadData', () => r.load(xml));
        // loadData returns 1/0 — and truncated-but-parseable XML returns 1 with
        // an empty score, so the load is only valid if notes actually exist.
        const doc = ok ? parseScoreDoc(xml) : null;
        if (!ok || !doc || doc.notes.length === 0) throw new Error('score load produced no content');
        const rendered = metrics.measure('renderPages', () => r.renderAllPages());
        setPages(rendered);
        setScoreDoc(doc);
        setDurationMs(r.durationMs());
        setRenderError(false);
        if (reason === 'switch') metrics.record('switch', performance.now() - tAll);
        if (reason === 'zoom') metrics.record('zoomRerender', performance.now() - tAll);
      } catch (e) {
        console.error('[UI-003] score render failed:', e);
        setPages([]);
        setRenderError(true);
      }
      bump();
    },
    [fixtureSet, view, zoom],
  );

  // Highlight helpers — pure DOM class toggles, no re-render (measured).
  const applyActiveDom = useCallback((canonicals: ReadonlySet<string>) => {
    const idx = indexRef.current;
    if (!idx) return;
    const t = performance.now();
    markCanonicalSet(idx, canonicals, ACTIVE_CLASS);
    metrics.record('highlightDom', performance.now() - t);
  }, []);

  const applyTime = useCallback(
    (ms: number) => {
      const r = rendererRef.current;
      setTimeMs(ms);
      if (!r) return;
      const t0 = performance.now();
      const res = r.elementsAtTime(ms);
      metrics.record('elementsAtTime', performance.now() - t0);
      const ids = res?.notes ?? [];
      setActiveExportIds(ids);
      const canonicals = new Set(
        ids.map((id) => canonicalNoteIdFromMusicxml(id)).filter((x): x is string => x !== null),
      );
      activeCanonicalsRef.current = canonicals;
      applyActiveDom(canonicals);
      bump();
    },
    [applyActiveDom],
  );

  const selectExportId = useCallback(
    (exportId: string) => {
      const r = rendererRef.current;
      const canonicalId = canonicalNoteIdFromMusicxml(exportId);
      // element → time + page (verovio APIs take the export id directly)
      const t0 = performance.now();
      const onset = r?.timeForElement(exportId) ?? null;
      metrics.record('timeForElement', performance.now() - t0);
      const page = r?.pageWithElement(exportId) ?? 0;
      const sel: Selection = { exportId, canonicalId, onsetMs: onset, page };
      selectionRef.current = sel;
      setSelection(sel);
      // DOM-only highlight of *all* rendered fragments of the canonical note
      const idx = indexRef.current;
      if (idx) {
        const t = performance.now();
        markCanonical(idx, canonicalId, SELECTED_CLASS);
        if (!canonicalId) {
          const el = idx.byExportId.get(exportId);
          el?.classList.add(SELECTED_CLASS);
        }
        metrics.record('highlightDom', performance.now() - t);
      }
      if (onset !== null) applyTime(onset);
      bump();
    },
    [applyTime],
  );

  // Init once.
  useEffect(() => {
    if (didInit.current) return;
    didInit.current = true;
    let cancelled = false;
    const t0 = performance.now();
    getScoreRenderer()
      .then((r) => {
        if (cancelled) return;
        rendererRef.current = r;
        metrics.record('wasmInit', performance.now() - t0);
        setVersion(r.version);
        renderScore('initial');
      })
      .catch((e: unknown) => setInitError(e instanceof Error ? e.message : String(e)));
    return () => {
      cancelled = true;
    };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  // After each (re)render of the SVG: rebuild the element index and reapply
  // selection/active highlights — this is also the path that proves canonical
  // selection survives renderer reload and Concert↔Horn switches.
  useLayoutEffect(() => {
    const container = scoreRef.current;
    if (!container || pages.length === 0) return;
    indexRef.current = buildElementIndex(container);
    const sel = selectionRef.current;
    if (sel?.canonicalId) {
      markCanonical(indexRef.current, sel.canonicalId, SELECTED_CLASS);
      const first = indexRef.current.byCanonical.get(sel.canonicalId)?.[0];
      first?.scrollIntoView({ block: 'nearest' });
    } else if (sel) {
      indexRef.current.byExportId.get(sel.exportId)?.classList.add(SELECTED_CLASS);
    }
    markCanonicalSet(indexRef.current, activeCanonicalsRef.current, ACTIVE_CLASS);
    bump();
  }, [pages]);

  // Ctrl+1 / Ctrl+2 presentation shortcuts (GUI_UX_PLAN §20).
  useEffect(() => {
    const onKey = (e: KeyboardEvent) => {
      const tag = (e.target as HTMLElement | null)?.tagName;
      if (tag === 'INPUT' || tag === 'SELECT' || tag === 'TEXTAREA') return;
      if (e.ctrlKey && e.key === '1') {
        e.preventDefault();
        switchView('concert');
      } else if (e.ctrlKey && e.key === '2') {
        e.preventDefault();
        if (supportsHorn(fixtureSet)) switchView('horn');
      }
    };
    window.addEventListener('keydown', onKey);
    return () => window.removeEventListener('keydown', onKey);
  });

  const switchView = useCallback(
    (v: PitchView) => {
      if (v === view) return;
      setView(v);
      renderScore('switch', { v });
    },
    [view, renderScore],
  );

  const changeFixture = useCallback(
    (setId: FixtureSetId) => {
      setFixtureSet(setId);
      const v: PitchView = supportsHorn(setId) ? view : 'concert';
      setView(v);
      selectionRef.current = null;
      setSelection(null);
      renderScore('fixture', { set: setId, v });
    },
    [view, renderScore],
  );

  const changeZoom = useCallback(
    (z: number) => {
      setZoom(z);
      renderScore('zoom', { z });
    },
    [renderScore],
  );

  const injectError = useCallback(() => renderScore('inject', { broken: true }), [renderScore]);
  const retryRender = useCallback(() => renderScore('retry'), [renderScore]);

  const selectedNote = selection
    ? scoreDoc?.notes.find((n) => n.exportId === selection.exportId) ?? null
    : null;

  const metricRows: { key: string; label: string }[] = [
    { key: 'wasmInit', label: spikeCopy.metricInit },
    { key: 'loadData', label: spikeCopy.metricLoad },
    { key: 'renderPages', label: spikeCopy.metricRender },
    { key: 'highlightDom', label: spikeCopy.metricHighlight },
    { key: 'elementsAtTime', label: spikeCopy.metricTimeQuery },
    { key: 'timeForElement', label: spikeCopy.metricElementTime },
    { key: 'switch', label: spikeCopy.metricSwitch },
    { key: 'zoomRerender', label: spikeCopy.metricZoom },
  ];

  return (
    <div className="hs-app">
      <header className="hs-header">
        <h1>{spikeCopy.title}</h1>
        <p className="hs-subtitle">{spikeCopy.subtitle}</p>
      </header>

      <div className="hs-toolbar" role="toolbar" aria-label={copy.score.toolbarAria}>
        <label className="hs-field">
          {spikeCopy.fixtureLabel}
          <select
            value={fixtureSet}
            onChange={(e) => changeFixture(e.target.value as FixtureSetId)}
          >
            <option value="golden">{spikeCopy.fixtures.golden}</option>
            <option value="minimal">{spikeCopy.fixtures.minimal}</option>
            <option value="multisystem">{spikeCopy.fixtures.multisystem}</option>
          </select>
        </label>

        <div className="hs-segment" role="group" aria-label={spikeCopy.viewSwitchAria}>
          <button
            type="button"
            aria-pressed={view === 'concert'}
            title={copy.seg.concertPitchTooltip}
            onClick={() => switchView('concert')}
          >
            {copy.seg.concertPitch}
          </button>
          <button
            type="button"
            aria-pressed={view === 'horn'}
            title={copy.seg.hornInFTooltip}
            disabled={!supportsHorn(fixtureSet)}
            onClick={() => switchView('horn')}
          >
            {copy.seg.hornInF}
          </button>
        </div>

        <div className="hs-zoom" role="group" aria-label={copy.score.zoomAria}>
          <button
            type="button"
            aria-label={spikeCopy.zoomOut}
            onClick={() => changeZoom(Math.max(25, zoom - 25))}
          >
            −
          </button>
          <input
            type="range"
            min={25}
            max={200}
            step={25}
            value={zoom}
            aria-label={spikeCopy.zoom}
            onChange={(e) => changeZoom(Number(e.target.value))}
          />
          <button
            type="button"
            aria-label={spikeCopy.zoomIn}
            onClick={() => changeZoom(Math.min(200, zoom + 25))}
          >
            ＋
          </button>
          <span className="hs-zoom-value">{zoom}%</span>
        </div>

        <button type="button" onClick={injectError} title={spikeCopy.injectErrorTooltip}>
          {spikeCopy.injectError}
        </button>
      </div>

      <div className="hs-timebar" role="group" aria-label={spikeCopy.timeLabel}>
        <label className="hs-field hs-time-field">
          {spikeCopy.timeLabel}
          <input
            type="range"
            min={0}
            max={Math.max(durationMs, 1)}
            step={10}
            value={timeMs}
            onChange={(e) => applyTime(Number(e.target.value))}
          />
        </label>
        <span className="hs-timecode">{(timeMs / 1000).toFixed(2)} 秒</span>
        <span className="hs-active-notes">
          {spikeCopy.activeAtTime}:{' '}
          {activeExportIds.length > 0
            ? activeExportIds
                .map((id) => `${id}→${canonicalNoteIdFromMusicxml(id) ?? '-'}`)
                .join('、')
            : spikeCopy.noActiveNotes}
        </span>
      </div>

      <main className="hs-main">
        {scoreDoc && (
          <NoteList
            heading={spikeCopy.noteListHeading}
            notes={scoreDoc.notes}
            selectedExportId={selection?.exportId ?? null}
            selectedCanonical={selection?.canonicalId ?? null}
            activeCanonicals={activeCanonicalsRef.current}
            onSelect={selectExportId}
          />
        )}

        <section className="hs-score-area">
          {initError ? (
            <div className="hs-error-panel" role="alert">
              <h2>{copy.renderFailed.title}</h2>
              <p>{initError}</p>
            </div>
          ) : renderError ? (
            <div className="hs-error-panel" role="alert">
              <h2>{copy.renderFailed.title}</h2>
              <p>{copy.renderFailed.body}</p>
              <button type="button" onClick={retryRender}>
                {copy.renderFailed.actions.retry}
              </button>
            </div>
          ) : pages.length === 0 ? (
            <p className="hs-loading">{spikeCopy.loading}…</p>
          ) : (
            <ScoreView
              ref={scoreRef}
              pages={pages}
              ariaLabel={copy.a11y.scoreRegion}
              onElementClick={selectExportId}
            />
          )}
        </section>

        <aside className="hs-side">
          <section aria-label={spikeCopy.selectionHeading}>
            <h2 className="hs-panel-title">{spikeCopy.selectionHeading}</h2>
            {selection === null ? (
              <p className="hs-dim">{spikeCopy.selectionEmpty}</p>
            ) : (
              <dl className="hs-props">
                <dt>{spikeCopy.canonicalId}</dt>
                <dd>
                  <code>{selection.canonicalId ?? spikeCopy.selectionRest}</code>
                </dd>
                <dt>{spikeCopy.exportId}</dt>
                <dd>
                  <code>{selection.exportId}</code>
                </dd>
                {selectedNote && (
                  <>
                    <dt>{spikeCopy.pitchField}</dt>
                    <dd>
                      {selectedNote.isRest ? '—' : pitchLabel(selectedNote)}{' '}
                      {describeNote(selectedNote)}
                    </dd>
                    <dt>{spikeCopy.measureField}</dt>
                    <dd>{selectedNote.measure}</dd>
                  </>
                )}
                <dt>{spikeCopy.onsetMs}</dt>
                <dd>{selection.onsetMs !== null ? `${selection.onsetMs} ms` : '—'}</dd>
                <dt>{spikeCopy.pagesLabel}</dt>
                <dd>{selection.page > 0 ? selection.page : '—'}</dd>
              </dl>
            )}
          </section>

          <section aria-label={spikeCopy.metricsHeading}>
            <h2 className="hs-panel-title">{spikeCopy.metricsHeading}</h2>
            <table className="hs-metrics">
              <tbody>
                {metricRows.map(({ key, label }) => {
                  const s = metrics.stats(key);
                  return (
                    <tr key={key}>
                      <th scope="row">{label}</th>
                      <td>
                        {s ? `${formatMs(s.last)}（平均 ${formatMs(s.avg)} / 最大 ${formatMs(s.max)} / ${s.count}回）` : '—'}
                      </td>
                    </tr>
                  );
                })}
                <tr>
                  <th scope="row">{spikeCopy.pagesLabel}</th>
                  <td>{pages.length || '—'}</td>
                </tr>
                <tr>
                  <th scope="row">{spikeCopy.notesLabel}</th>
                  <td>{indexRef.current?.noteCount ?? '—'}</td>
                </tr>
                <tr>
                  <th scope="row">{spikeCopy.dprLabel}</th>
                  <td>{window.devicePixelRatio}</td>
                </tr>
                <tr>
                  <th scope="row">{spikeCopy.versionLabel}</th>
                  <td>{version || '—'}</td>
                </tr>
              </tbody>
            </table>
          </section>
        </aside>
      </main>
    </div>
  );
}

import { useCallback, useRef } from 'react';
import { describeNote, type ParsedNote } from '../lib/scoreDoc';

interface NoteListProps {
  heading: string;
  notes: ParsedNote[];
  selectedExportId: string | null;
  selectedCanonical: string | null;
  activeCanonicals: ReadonlySet<string>;
  onSelect: (exportId: string) => void;
}

/**
 * Parallel accessible representation of the score: a real `listbox` of notes
 * and rests grouped by measure, independent of the SVG. Arrow keys move,
 * Enter/Space selects — this is the keyboard/screen-reader path that GUI_UX_PLAN
 * §40 requires so a11y never relies on the raw SVG tree.
 */
export function NoteList({
  heading,
  notes,
  selectedExportId,
  selectedCanonical,
  activeCanonicals,
  onSelect,
}: NoteListProps) {
  const listRef = useRef<HTMLUListElement>(null);
  const items = notes;

  const isSelected = (n: ParsedNote) =>
    n.exportId === selectedExportId ||
    (n.canonicalId !== null && n.canonicalId === selectedCanonical);
  const isActive = (n: ParsedNote) => n.canonicalId !== null && activeCanonicals.has(n.canonicalId);

  const focusIndex = useCallback((idx: number) => {
    const el = listRef.current?.querySelectorAll<HTMLElement>('[role="option"]')[idx];
    el?.focus();
  }, []);

  const onKeyDown = useCallback(
    (e: React.KeyboardEvent) => {
      const current = document.activeElement;
      const options = Array.from(
        listRef.current?.querySelectorAll<HTMLElement>('[role="option"]') ?? [],
      );
      const idx = options.indexOf(current as HTMLElement);
      if (e.key === 'ArrowDown' || e.key === 'ArrowRight') {
        e.preventDefault();
        focusIndex(Math.min(options.length - 1, idx + 1));
      } else if (e.key === 'ArrowUp' || e.key === 'ArrowLeft') {
        e.preventDefault();
        focusIndex(Math.max(0, idx <= 0 ? 0 : idx - 1));
      } else if ((e.key === 'Enter' || e.key === ' ') && idx >= 0) {
        e.preventDefault();
        onSelect(items[idx].exportId);
      }
    },
    [focusIndex, items, onSelect],
  );

  return (
    <section className="hs-notelist" aria-label={heading}>
      <h2 className="hs-panel-title">{heading}</h2>
      <ul
        ref={listRef}
        role="listbox"
        aria-label={heading}
        className="hs-notelist-ul"
        onKeyDown={onKeyDown}
      >
        {items.map((n, i) => {
          const selected = isSelected(n);
          const active = isActive(n);
          return (
            <li
              key={n.exportId}
              role="option"
              aria-selected={selected}
              tabIndex={i === 0 || selected ? 0 : -1}
              className={
                'hs-note-option' +
                (selected ? ' is-selected' : '') +
                (active ? ' is-active' : '')
              }
              onClick={() => onSelect(n.exportId)}
            >
              <span className="hs-note-option-text">
                {active ? '▶ ' : ''}
                {describeNote(n)}
              </span>
              <code className="hs-note-option-id">{n.exportId}</code>
            </li>
          );
        })}
      </ul>
    </section>
  );
}

import { forwardRef, useCallback } from 'react';
import type { RenderedPage } from '../lib/verovio';
import { resolveHitElement } from '../lib/domScore';

interface ScoreViewProps {
  pages: RenderedPage[];
  /** Called with the MusicXML export id (`hs-*`) of the clicked note/rest. */
  onElementClick: (exportId: string) => void;
  ariaLabel: string;
}

/**
 * Renders Verovio's per-page SVG. The raw SVG is `aria-hidden`: the parallel
 * listbox (NoteList) is the accessible representation, so hit-testing and
 * semantics never depend on SVG internals alone (GUI_UX_PLAN §40).
 */
export const ScoreView = forwardRef<HTMLDivElement, ScoreViewProps>(function ScoreView(
  { pages, onElementClick, ariaLabel },
  ref,
) {
  const handleClick = useCallback(
    (e: React.MouseEvent<HTMLDivElement>) => {
      const container = e.currentTarget;
      const hit = resolveHitElement(e.target, container);
      if (hit?.id) onElementClick(hit.id);
    },
    [onElementClick],
  );

  return (
    <div
      ref={ref}
      className="hs-score-scroll"
      role="region"
      aria-label={ariaLabel}
      onClick={handleClick}
    >
      <div className="hs-score-pages" aria-hidden="true">
        {pages.map((p) => (
          <div
            key={p.page}
            className="hs-score-page"
            data-page={p.page}
            dangerouslySetInnerHTML={{ __html: p.svg }}
          />
        ))}
      </div>
    </div>
  );
});

/**
 * ENG-001 fixtures are imported with `?raw` — bundled at build time, so the
 * spike runs fully offline and exercises the exact committed bytes.
 * `multisystem` is a spike-local deterministic fixture (see
 * `scripts/gen-multisystem.mjs`) that adds multi-system + multi-page layout.
 */
import goldenConcert from '../../../../fixtures/musicxml/golden_v1_concert.musicxml?raw';
import goldenHorn from '../../../../fixtures/musicxml/golden_v1_horn_in_f.musicxml?raw';
import minimalConcert from '../../../../fixtures/musicxml/minimal_v1_concert.musicxml?raw';
import minimalHorn from '../../../../fixtures/musicxml/minimal_v1_horn_in_f.musicxml?raw';
import multisystemConcert from '../fixtures/multisystem_concert.musicxml?raw';

export type FixtureSetId = 'golden' | 'minimal' | 'multisystem';
export type PitchView = 'concert' | 'horn';

export interface FixtureSet {
  id: FixtureSetId;
  concert: string;
  /** undefined for spike-local sets with no Horn presentation yet. */
  horn?: string;
}

export const FIXTURE_SETS: Record<FixtureSetId, FixtureSet> = {
  golden: { id: 'golden', concert: goldenConcert, horn: goldenHorn },
  minimal: { id: 'minimal', concert: minimalConcert, horn: minimalHorn },
  multisystem: { id: 'multisystem', concert: multisystemConcert },
};

export function fixtureXml(set: FixtureSetId, view: PitchView): string {
  const f = FIXTURE_SETS[set];
  return view === 'horn' && f.horn ? f.horn : f.concert;
}

export function supportsHorn(set: FixtureSetId): boolean {
  return FIXTURE_SETS[set].horn !== undefined;
}

/**
 * DOM-side helpers for the rendered Verovio SVG.
 *
 * Verovio mirrors the MusicXML `note/@id` onto the rendered element
 * (`<g class="note" id="hs-sn-000003">`), so a rendered element can be looked
 * up by export id and resolved to a canonical `sn-*` id. Highlighting is a
 * pure `classList` toggle — no re-render (measured in the spike results).
 */
import { canonicalNoteIdFromMusicxml, isMusicxmlNoteId } from './ids';

export interface ElementIndex {
  /** export id (`hs-sn-000003-2`) → rendered <g> element */
  byExportId: Map<string, Element>;
  /** canonical id (`sn-000003`) → all rendered fragments */
  byCanonical: Map<string, Element[]>;
  noteCount: number;
}

export const SELECTED_CLASS = 'hs-selected';
export const ACTIVE_CLASS = 'hs-active';
export const HIT_CLASS = 'hs-hit';

const SVG_NS = 'http://www.w3.org/2000/svg';

/**
 * Append an invisible hit ellipse over each note/rest glyph.
 *
 * Finding (UI-003): Verovio paints noteheads as font glyphs, and a hollow
 * notehead (half/whole note) is *transparent in the middle* — a click at its
 * centre falls through to the <svg> background. Relying on glyph paint for
 * hit-testing is therefore unreliable; the production-safe pattern is an
 * explicit transparent overlay inside each id-bearing group.
 */
function addHitShape(el: Element): void {
  if (typeof (el as SVGGElement).getBBox !== 'function') return; // jsdom etc.
  try {
    const head = el.querySelector('.notehead') ?? el.querySelector('use') ?? el;
    const box = (head as SVGGElement).getBBox();
    if (!box || box.width <= 0 || box.height <= 0) return;
    const pad = Math.max(box.width, box.height) * 0.35;
    const hit = document.createElementNS(SVG_NS, 'ellipse');
    hit.setAttribute('cx', String(box.x + box.width / 2));
    hit.setAttribute('cy', String(box.y + box.height / 2));
    hit.setAttribute('rx', String(box.width / 2 + pad));
    hit.setAttribute('ry', String(box.height / 2 + pad));
    hit.setAttribute('class', HIT_CLASS);
    // Append inside the notehead group so the ellipse shares the glyph's
    // coordinate space; closest('[id^=hs-]') still resolves the note group.
    head.appendChild(hit);
  } catch {
    /* getBBox unsupported — skip hit shape (non-browser env) */
  }
}

/** Index every Verovio element carrying a HornScribe export id. */
export function buildElementIndex(container: Element): ElementIndex {
  const byExportId = new Map<string, Element>();
  const byCanonical = new Map<string, Element[]>();
  let noteCount = 0;
  for (const el of Array.from(container.querySelectorAll('[id^="hs-"]'))) {
    const id = el.id;
    if (!isMusicxmlNoteId(id) && !id.startsWith('hs-rest-')) continue;
    byExportId.set(id, el);
    addHitShape(el);
    const canonical = canonicalNoteIdFromMusicxml(id);
    if (canonical) {
      noteCount++;
      const list = byCanonical.get(canonical) ?? [];
      list.push(el);
      byCanonical.set(canonical, list);
    }
  }
  return { byExportId, byCanonical, noteCount };
}

/** Hit-test a click target up to the note/rest group carrying the id. */
export function resolveHitElement(target: EventTarget | null, container: Element): Element | null {
  if (!(target instanceof Element)) return null;
  const hit = target.closest('[id^="hs-"]');
  return hit && container.contains(hit) ? hit : null;
}

function setClass(elements: Iterable<Element>, cls: string, on: boolean): number {
  let n = 0;
  for (const el of elements) {
    el.classList.toggle(cls, on);
    n++;
  }
  return n;
}

/** Clear then apply `cls` to every rendered fragment of `canonicalId`. */
export function markCanonical(
  index: ElementIndex,
  canonicalId: string | null,
  cls: string,
): number {
  for (const el of Array.from(index.byExportId.values())) el.classList.remove(cls);
  if (!canonicalId) return 0;
  return setClass(index.byCanonical.get(canonicalId) ?? [], cls, true);
}

/** Apply `cls` to a set of canonical ids without clearing the selection class. */
export function markCanonicalSet(
  index: ElementIndex,
  canonicalIds: ReadonlySet<string>,
  cls: string,
): number {
  for (const el of Array.from(index.byExportId.values())) el.classList.remove(cls);
  let n = 0;
  for (const id of canonicalIds) n += setClass(index.byCanonical.get(id) ?? [], cls, true);
  return n;
}

/**
 * TypeScript mirror of the FND-001 identity rules
 * (`python/hornscribe/domain/ids.py`, `docs/CONTRACTS.md` §1).
 *
 *   canonical note        sn-<6 digits>
 *   MusicXML note/@id     hs-sn-<6 digits>
 *   MusicXML tied fragment hs-sn-<6 digits>-<k>   (k > 1)
 *   MusicXML rest          hs-rest-<6 digits>     (presentation-only)
 *
 * Every `hs-sn-*` export id — fragment or not — resolves back to exactly one
 * `sn-*` canonical note id. `hs-rest-*` deliberately has no canonical target.
 */

const SCORE_NOTE_RE = /^sn-\d{6}$/;
const MUSICXML_NOTE_RE = /^hs-sn-\d{6}(?:-\d+)?$/;
const MUSICXML_REST_RE = /^hs-rest-\d{6}$/;
const CANONICAL_PART_RE = /^hs-(sn-\d{6})/;

export function isScoreNoteId(value: string): boolean {
  return SCORE_NOTE_RE.test(value);
}

export function isMusicxmlNoteId(value: string): boolean {
  return MUSICXML_NOTE_RE.test(value);
}

export function isMusicxmlRestId(value: string): boolean {
  return MUSICXML_REST_RE.test(value);
}

/** `sn-000042` -> `hs-sn-000042` (fragment 1), `hs-sn-000042-2` (fragment 2), … */
export function musicxmlNoteId(canonicalId: string, fragment = 1): string {
  if (!isScoreNoteId(canonicalId)) {
    throw new Error(`not a canonical score note id: ${canonicalId}`);
  }
  if (fragment < 1) {
    throw new Error(`fragment must be >= 1, got ${fragment}`);
  }
  return fragment === 1 ? `hs-${canonicalId}` : `hs-${canonicalId}-${fragment}`;
}

/**
 * `hs-sn-000042` -> `sn-000042`; `hs-sn-000042-3` -> `sn-000042`.
 * Returns null for anything that is not a canonical-backed export id
 * (e.g. `hs-rest-*`, or a Verovio-generated id like `d1e123`).
 */
export function canonicalNoteIdFromMusicxml(exportId: string): string | null {
  if (!isMusicxmlNoteId(exportId)) return null;
  const match = CANONICAL_PART_RE.exec(exportId);
  return match ? match[1] : null;
}

/** Tiny measurement recorder for spike evidence (GUI_UX_PLAN §46 budgets). */

export interface MetricStats {
  count: number;
  last: number;
  min: number;
  max: number;
  avg: number;
}

export class Metrics {
  private samples = new Map<string, number[]>();

  record(label: string, ms: number): number {
    const list = this.samples.get(label) ?? [];
    list.push(ms);
    this.samples.set(label, list);
    return ms;
  }

  /** Time a synchronous call, record under `label`, return the call result. */
  measure<T>(label: string, fn: () => T): T {
    const t0 = performance.now();
    try {
      return fn();
    } finally {
      this.record(label, performance.now() - t0);
    }
  }

  stats(label: string): MetricStats | null {
    const list = this.samples.get(label);
    if (!list || list.length === 0) return null;
    const sum = list.reduce((a, b) => a + b, 0);
    return {
      count: list.length,
      last: list[list.length - 1],
      min: Math.min(...list),
      max: Math.max(...list),
      avg: sum / list.length,
    };
  }

  labels(): string[] {
    return [...this.samples.keys()];
  }
}

export const metrics = new Metrics();

export function formatMs(ms: number): string {
  return ms < 10 ? `${ms.toFixed(2)} ms` : `${ms.toFixed(1)} ms`;
}

/**
 * MusicXML → flat note/rest model used for the parallel accessible score
 * representation (GUI_UX_PLAN §40: a11y must not depend on raw SVG alone).
 * This is a presentation helper only — canonical identity still comes from
 * `hs-sn-*` ids, not from parse order.
 */
import { canonicalNoteIdFromMusicxml, isMusicxmlRestId } from './ids';

export interface ParsedNote {
  exportId: string; // MusicXML note/@id, e.g. hs-sn-000003-2 / hs-rest-000001
  canonicalId: string | null; // sn-000003, or null for rests
  isRest: boolean;
  measure: number;
  step?: string;
  alter?: number;
  octave?: number;
  type?: string;
  dots: number;
  /** This note is a member of a tie chain (start/stop). */
  tied: boolean;
}

export interface ScoreDoc {
  title: string;
  notes: ParsedNote[];
  measureCount: number;
}

const TYPE_JA: Record<string, string> = {
  whole: '全',
  half: '二分',
  quarter: '四分',
  eighth: '八分',
  '16th': '十六分',
  '32nd': '三十二分',
  '64th': '六十四分',
};

export function noteTypeJa(note: ParsedNote): string {
  const base = TYPE_JA[note.type ?? ''] ?? (note.type ?? '');
  const dotted = note.dots > 0 ? '付点' : '';
  const unit = note.isRest ? '休符' : '音符';
  return `${dotted}${base}${unit}`.replace(/^付点$/, '');
}

export function pitchLabel(note: ParsedNote): string {
  if (note.isRest || note.step === undefined || note.octave === undefined) return '';
  const acc = note.alter === undefined || note.alter === 0 ? '' : note.alter > 0 ? '♯'.repeat(note.alter) : '♭'.repeat(-note.alter);
  return `${note.step}${acc}${note.octave}`;
}

/** e.g. "第3小節 B♭3 付点四分音符 (sn-000003)" / "第2小節 四分休符" */
export function describeNote(note: ParsedNote): string {
  const where = `第${note.measure}小節`;
  if (note.isRest) return `${where} ${noteTypeJa(note)}`;
  const pitch = pitchLabel(note);
  const tie = note.tied ? '・タイ' : '';
  return `${where} ${pitch} ${noteTypeJa(note)}${tie}`;
}

export function parseScoreDoc(xml: string): ScoreDoc {
  const doc = new DOMParser().parseFromString(xml, 'application/xml');
  const title =
    doc.querySelector('movement-title')?.textContent?.trim() ||
    doc.querySelector('work-title')?.textContent?.trim() ||
    '';
  const notes: ParsedNote[] = [];
  let measureCount = 0;
  for (const measure of Array.from(doc.querySelectorAll('part > measure'))) {
    const number = Number(measure.getAttribute('number') ?? measureCount + 1);
    measureCount = Math.max(measureCount, Number.isFinite(number) ? number : measureCount + 1);
    for (const noteEl of Array.from(measure.querySelectorAll(':scope > note'))) {
      const exportId = noteEl.getAttribute('id') ?? '';
      const isRest = noteEl.querySelector('rest') !== null || isMusicxmlRestId(exportId);
      const pitchEl = noteEl.querySelector('pitch');
      const alterText = pitchEl?.querySelector('alter')?.textContent;
      const tied =
        noteEl.querySelector('tie[type="start"], tie[type="stop"]') !== null ||
        noteEl.querySelector('notations > tied') !== null;
      notes.push({
        exportId,
        canonicalId: canonicalNoteIdFromMusicxml(exportId),
        isRest,
        measure: number,
        step: pitchEl?.querySelector('step')?.textContent ?? undefined,
        alter: alterText !== undefined && alterText !== null ? Number(alterText) : undefined,
        octave: pitchEl?.querySelector('octave')?.textContent
          ? Number(pitchEl.querySelector('octave')!.textContent)
          : undefined,
        type: noteEl.querySelector('type')?.textContent ?? undefined,
        dots: noteEl.querySelectorAll('dot').length,
        tied,
      });
    }
  }
  return { title, notes, measureCount };
}

/**
 * Thin wrapper around the Verovio WASM toolkit used by the spike.
 *
 * `verovio/wasm` inlines the WASM binary inside `dist/verovio-module.mjs`, so
 * module instantiation needs no network fetch and no .wasm asset pipeline —
 * that property is what keeps the spike (and later the Tauri shell) fully
 * offline without CSP workarounds beyond the script bundle itself.
 */
import createVerovioModule, { type VerovioModule } from 'verovio/wasm';
import {
  VerovioToolkit,
  type VerovioElementsAtTime,
  type VerovioTimemapEntry,
  type VerovioTimesForElement,
} from 'verovio/esm';

export interface RenderedPage {
  page: number;
  svg: string;
}

/** Baseline engraving options. `pageHeight` is short on purpose so the
 *  multi-system fixture paginates and `getPageWithElement` is exercised. */
const BASE_OPTIONS = {
  pageWidth: 2100,
  pageHeight: 1100,
  scale: 40,
  adjustPageHeight: false,
  footer: 'none',
  breaks: 'auto',
} as const;

export class ScoreRenderer {
  private toolkit: VerovioToolkit | null = null;
  private zoomPct = 100;

  get version(): string {
    return this.toolkit?.getVersion() ?? 'unknown';
  }

  async init(): Promise<void> {
    if (this.toolkit) return;
    const mod: VerovioModule = await createVerovioModule();
    this.toolkit = new VerovioToolkit(mod);
    this.toolkit.setOptions({ ...BASE_OPTIONS });
  }

  private tk(): VerovioToolkit {
    if (!this.toolkit) throw new Error('ScoreRenderer not initialized');
    return this.toolkit;
  }

  /** Returns true when Verovio accepted the document. */
  load(musicXml: string): boolean {
    return this.tk().loadData(musicXml);
  }

  setZoom(pct: number): void {
    this.zoomPct = pct;
    this.tk().setOptions({
      ...BASE_OPTIONS,
      // Verovio `scale` is a percent-like zoom factor (default 40). Pagination
      // is stable across scale changes because page size scales with it.
      scale: Math.max(10, Math.round((40 * pct) / 100)),
    });
  }

  getZoom(): number {
    return this.zoomPct;
  }

  pageCount(): number {
    return this.tk().getPageCount();
  }

  /** Render every page; page index is 1-based like `renderToSVG`.
   *  Page 1 is rendered first so the layout (and therefore `getPageCount`)
   *  reflects the current options before counting. */
  renderAllPages(): RenderedPage[] {
    const tk = this.tk();
    const first = tk.renderToSVG(1);
    const count = tk.getPageCount();
    const pages: RenderedPage[] = [{ page: 1, svg: first }];
    for (let page = 2; page <= count; page++) {
      pages.push({ page, svg: tk.renderToSVG(page) });
    }
    return pages;
  }

  /** Parsed timemap; must be (re)built after each `load`.
   *  verovio >= 4.x returns an already-parsed array (the ESM wrapper
   *  JSON.parses internally); older builds returned a raw string — accept both. */
  timemap(): VerovioTimemapEntry[] {
    const raw = this.tk().renderToTimemap() as unknown;
    if (typeof raw === 'string') return JSON.parse(raw) as VerovioTimemapEntry[];
    return raw as VerovioTimemapEntry[];
  }

  durationMs(): number {
    const map = this.timemap();
    let max = 0;
    for (const entry of map) max = Math.max(max, entry.tstamp);
    return max;
  }

  /** ms onset for an element id (e.g. `hs-sn-000003-2`), or null if unknown. */
  timeForElement(id: string): number | null {
    try {
      const t = this.tk().getTimeForElement(id);
      return Number.isFinite(t) && t >= 0 ? t : null;
    } catch {
      return null;
    }
  }

  timesForElement(id: string): VerovioTimesForElement | null {
    try {
      return this.tk().getTimesForElement(id);
    } catch {
      return null;
    }
  }

  elementsAtTime(ms: number): VerovioElementsAtTime | null {
    try {
      return this.tk().getElementsAtTime(ms);
    } catch {
      return null;
    }
  }

  /** 1-based page containing the element, 0 when not found. */
  pageWithElement(id: string): number {
    try {
      return this.tk().getPageWithElement(id);
    } catch {
      return 0;
    }
  }
}

/** Lazy singleton — survives React StrictMode double-mount and hot reloads. */
let rendererPromise: Promise<ScoreRenderer> | null = null;
export function getScoreRenderer(): Promise<ScoreRenderer> {
  if (!rendererPromise) {
    const renderer = new ScoreRenderer();
    rendererPromise = renderer.init().then(() => renderer);
  }
  return rendererPromise;
}

import { StrictMode } from 'react';
import { createRoot } from 'react-dom/client';
